import{_ as o,o as a,c as i,a2 as s}from"./chunks/framework.CHeM0PsO.js";const m=JSON.parse('{"title":"Postagens","description":"","frontmatter":{"status":"rascunho","tipo":"modulo","area":"postagens","atualizado_em":"2026-08-03T00:00:00.000Z"},"headers":[],"relativePath":"planejamento/modulos/postagens.md","filePath":"planejamento/modulos/postagens.md","lastUpdated":null}'),t={name:"planejamento/modulos/postagens.md"};function l(r,e,n,d,c,u){return a(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="postagens" tabindex="-1">Postagens <a class="header-anchor" href="#postagens" aria-label="Permalink to &quot;Postagens&quot;">​</a></h1><h2 id="objetivo" tabindex="-1">Objetivo <a class="header-anchor" href="#objetivo" aria-label="Permalink to &quot;Objetivo&quot;">​</a></h2><p>Gerenciar conteudos editoriais, como noticias, colunas, reviews e eventos publicados no site.</p><h2 id="escopos-atuais" tabindex="-1">Escopos Atuais <a class="header-anchor" href="#escopos-atuais" aria-label="Permalink to &quot;Escopos Atuais&quot;">​</a></h2><ul><li>Criacao de posts.</li><li>Edicao de posts.</li><li>Leitura individual no painel.</li><li>Desativacao de posts.</li><li>Comentarios, reacoes e curtidas no publico.</li><li>Feed externo de noticias de anime.</li></ul><h2 id="funcionalidades" tabindex="-1">Funcionalidades <a class="header-anchor" href="#funcionalidades" aria-label="Permalink to &quot;Funcionalidades&quot;">​</a></h2><ul><li>Listar posts ativos com paginacao.</li><li>Buscar posts por termo.</li><li>Exibir posts com contagem de visualizacoes.</li><li>Filtrar acesso de acordo com o usuario autenticado.</li><li>Consultar fontes e itens do feed externo quando o usuario tiver permissao.</li></ul><h2 id="arquivos-envolvidos" tabindex="-1">Arquivos Envolvidos <a class="header-anchor" href="#arquivos-envolvidos" aria-label="Permalink to &quot;Arquivos Envolvidos&quot;">​</a></h2><ul><li>Pagina: <code>resources/js/pages/private/Post.svelte</code>.</li><li>Controller de pagina: <code>PostPageController</code>.</li><li>Controller de recurso: <code>PostController</code>.</li><li>Invokes: <code>DeactivatePostController</code>.</li><li>Service: <code>AnimeNewsFeedService</code>.</li><li>Filter: <code>PostFilter</code>.</li><li>Resource: <code>PostResource</code>.</li><li>Models: <code>Post</code>, <code>PostTag</code>, <code>PostReference</code>, <code>PostReview</code>, <code>PostComment</code>, <code>PostReaction</code>, <code>PostLike</code>.</li></ul><h2 id="permissoes" tabindex="-1">Permissoes <a class="header-anchor" href="#permissoes" aria-label="Permalink to &quot;Permissoes&quot;">​</a></h2><ul><li><code>post.module.view</code> controla acesso ao modulo no menu.</li><li><code>post.feed.view</code> controla acesso ao feed externo.</li><li>Regras principais ficam em <code>PostPolicy</code>.</li></ul><h2 id="riscos" tabindex="-1">Riscos <a class="header-anchor" href="#riscos" aria-label="Permalink to &quot;Riscos&quot;">​</a></h2><ul><li>O modelo <code>Post</code> concentra tipos diferentes de conteudo.</li><li>Reviews, eventos e materias precisam ter regras claras para evitar campos opcionais confusos.</li><li>Feed externo precisa de tratamento para indisponibilidade do servico.</li></ul><h2 id="planejamento" tabindex="-1">Planejamento <a class="header-anchor" href="#planejamento" aria-label="Permalink to &quot;Planejamento&quot;">​</a></h2><ul><li>[ ] Documentar tipos de conteudo suportados.</li><li>[ ] Definir fluxo de revisao editorial.</li><li>[ ] Mapear tags, referencias e extensoes de review.</li><li>[ ] Registrar regras para conteudo publico versus privado.</li></ul><h2 id="referencias" tabindex="-1">Referencias <a class="header-anchor" href="#referencias" aria-label="Permalink to &quot;Referencias&quot;">​</a></h2><ul><li><a href="./dashboard">dashboard</a></li><li><a href="./marketing">marketing</a></li></ul>',17)])])}const h=o(t,[["render",l]]);export{m as __pageData,h as default};
